// Workflow preview only. Approval, identity, and department checks must be enforced server-side before staff rollout.
db.joinRequests??=[];db.dailyAssignments??=[];db.coachSessions??=[];db.salesLeads??=[];
const teamRender=render;navs.push(['join','＋','تسجيل موظف جديد'],['join-approvals','✓','طلبات الانضمام'],['daily-team','☑','مهام الموظفين'],['coach-log','♙','سجل المدربين'],['sales-work','▤','متابعة السيلز']);
const departments=['التدريب','السيلز','الهاوس كيبنج','الجودة','الموارد البشرية','الأسسمنت والعلاج الطبيعي','Outdoor','Move'];const positions={'كابتن':'التدريب','سيلز':'السيلز','هاوس كيبنج':'الهاوس كيبنج','كواليتي':'الجودة','HR':'الموارد البشرية','أسسمنت — دكتور علاج طبيعي':'الأسسمنت والعلاج الطبيعي','Outdoor':'Outdoor','Move':'Move'};let managerDepartment='التدريب',taskDay=cairoDay(),coachDay=cairoDay(),salesStage='all',salesSource='all',salesQuery='';
const taskTemplates=['ترتيب الفلور والمعدات بعد الاستخدام','التأكد من نظافة المكان','التأكد من تشغيل التكييفات والإبلاغ عن الأعطال'];
const leadSources=['old data','expired','invitation','social media','rank','other'];const leadStages=['Source','Open','Follow','Close'];const callOutcomes=['رد','لم يرد','مشغول','مهتم','غير مهتم','اشترك'];
function employeeDepartment(s){return s.department||positions[s.position]||(/مدرب|مدربة|كابتن/.test(s.job)?'التدريب':/استقبال|سيلز|مبيعات|عملاء/.test(s.job)?'السيلز':'الهاوس كيبنج')}
function demoManagerCan(s){return role==='الإدارة'||(role==='مدير قسم'&&employeeDepartment(s)===managerDepartment&&($('#branch').value==='كل الفروع'||$('#branch').value===s.branch))}
function scopedTeam(){return db.staff.filter(s=>demoManagerCan(s))}
function displayTeam(){return role==='الموظف'?[currentEmployee()].filter(Boolean):scopedTeam()}
function pickEmployees(name,people,value=''){return `<select name="${name}" id="${name}">${people.map(s=>`<option value="${s.id}" ${String(s.id)===String(value)?'selected':''}>${esc(s.name)} — ${esc(employeeDepartment(s))}</option>`).join('')}</select>`}
function validPhone(raw){const value=String(raw||'').trim().replace(/[٠-٩]/g,c=>c.charCodeAt(0)-1632).replace(/[\s()-]/g,'');if(!/^\+?\d{8,15}$/.test(value))throw Error('راجع رقم الهاتف: من ٨ إلى ١٥ رقم');return value}
function requiredText(value,label,max=1000){const s=String(value||'').trim();if(!s||s.length>max)throw Error('اكتب '+label+' بشكل صحيح');return s}
function newJoin(data){const name=requiredText(data.name,'الاسم',120),email=String(data.email||'').trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('البريد الإلكتروني غير صحيح');if(!positions[data.position])throw Error('اختار الوظيفة');if(!db.branches.some(b=>b.name===data.branch))throw Error('الفرع غير موجود');if(db.joinRequests.some(r=>r.email===email&&r.status!=='rejected')||db.staff.some(s=>s.email===email))throw Error('البريد له طلب قائم أو موظف بالفعل');const r={id:crypto.randomUUID(),name,email,phone:validPhone(data.phone),position:data.position,branch:data.branch,status:'pending',createdAt:new Date().toISOString()};db.joinRequests.push(r);audit('طلب انضمام محلي جديد: '+name);return r}
function approveJoin(id,position,branch){if(role!=='الإدارة')throw Error('القبول من الإدارة فقط');const r=db.joinRequests.find(r=>r.id===id);if(!r||r.status!=='pending')throw Error('الطلب اتراجع بالفعل');if(!positions[position]||!db.branches.some(b=>b.name===branch))throw Error('حدد الوظيفة والفرع');let employeeId=Date.now();while(db.staff.some(s=>s.id===employeeId)||db.archived.some(s=>s.id===employeeId))employeeId++;const s={id:employeeId,name:r.name,email:r.email,phone:r.phone,job:position,position,department:positions[position],branch,time:'—',status:'غائب',salary:0,joinRequestId:r.id,approvalStatus:'approved'};db.staff.push(s);db.accounts.push({id:crypto.randomUUID(),name:s.name,email:s.email,type:'موظف',branches:[branch],permissions:['self_attendance','self_tasks',...(position==='كابتن'?['self_coach_log']:position==='سيلز'?['self_sales']:[])],employeeId:s.id,disabled:false,createdAt:new Date().toISOString(),provisioned:false});r.status='approved';r.employeeId=s.id;r.approvedPosition=position;r.reviewedAt=new Date().toISOString();audit('موافقة أولى محلية: '+s.name+' — '+position);return s}
function joinView(){return `<div class="notice" data-preview-only>معاينة تسجيل فقط: لا ينشئ حساب دخول أو باسورد. الطلب والموافقة محفوظان على نفس المتصفح لحين ربط الحسابات الفعلية.</div>${card('انضم لفريق Energy Club',`<form id="joinForm" class="join-form"><div class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h2>مكانك في الفريق يبدأ من هنا.</h2><p>سجل بياناتك وحدد وظيفتك. الإدارة تراجع طلبك وتحدد الأكسس المناسب بعد الموافقة الأولى.</p>${field('الاسم الكامل','name')}${field('البريد الإلكتروني','email','email')}${field('رقم الموبايل','phone','tel')}${options('بطلب الانضمام كـ','position',Object.keys(positions))}${options('الفرع','branch',db.branches.map(b=>b.name))}<button class="primary">إرسال طلب انضمام للمعاينة</button><p id="joinResult" role="status"></p></form>`)}${card('طلبات المعاينة على هذا المتصفح',db.joinRequests.map(r=>`<div class="request"><div class="details"><strong>${esc(r.name)}</strong><p>${esc(r.position)} • ${esc(r.branch)}</p></div>${badge(r.status==='pending'?'بانتظار الموافقة':r.status==='approved'?'مقبول محليًا':'مرفوض')}</div>`).join('')||'<p class="empty">لا توجد طلبات حتى الآن</p>')}`}
function approvalsView(){return card('طلبات التسجيل — الموافقة الأولى',db.joinRequests.map(r=>`<div class="request"><div class="details"><strong>${esc(r.name)}</strong><p>${esc(r.email)} • ${esc(r.phone)}<br>طلب: ${esc(r.position)} — ${esc(r.branch)}</p>${r.reason?`<p>سبب الرفض: ${esc(r.reason)}</p>`:''}</div>${r.status==='pending'?`<button data-join-approve="${r.id}">مراجعة وقبول</button><button class="reject" data-join-reject="${r.id}">رفض بسبب</button>`:badge(r.status==='approved'?'تم القبول':'مرفوض')}</div>`).join('')||'<p class="empty">طلبات الموظفين الجديدة هتظهر هنا</p>')}
function createAssignment(data){const s=db.staff.find(s=>s.id===Number(data.employeeId));if(!s||!demoManagerCan(s))throw Error('الموظف خارج نطاق فريقك');if(!/^\d{4}-\d\d-\d\d$/.test(data.day))throw Error('اختار يوم المهمة');if(typeof nodeUser==='undefined'||!nodeUser||nodeUser.role==='admin'){if(data.repeatTo){if(!/^\d{4}-\d\d-\d\d$/.test(data.repeatTo)||data.repeatTo<data.day)throw Error('اختار تاريخ تكرار صحيح بعد يوم البداية');const start=new Date(data.day+'T12:00:00Z').getTime(),end=new Date(data.repeatTo+'T12:00:00Z').getTime();if(end-start>30*86400000)throw Error('أقصى مدة للتكرار ٣١ يومًا');let made=0;for(let t=start;t<=end;t+=86400000){const day=new Date(t).toISOString().slice(0,10);made+=createAssignment({...data,day,repeatTo:undefined})?1:0}return made?{id:'repeat'}:null}const title=requiredText(data.title,'عنوان المهمة',240);if(db.dailyAssignments.some(t=>Number(t.employeeId)===s.id&&t.day===data.day&&t.title===title))return null;const task={id:crypto.randomUUID(),employeeId:s.id,employeeName:s.name,department:employeeDepartment(s),branch:s.branch,day:data.day,title,notes:String(data.notes||'').trim(),status:'assigned',createdAt:new Date().toISOString(),assignedBy:role==='الإدارة'?'الإدارة':'مدير قسم '+managerDepartment};db.dailyAssignments.push(task);audit('تكليف '+s.name+': '+title);return task}return nativeAction('task_assign',data)}
function taskForm(){const people=scopedTeam();if(!people.length)return toast('لا يوجد موظفون في نطاق القسم');safeSubmit('إضافة مهمة لموظف',`<label>الموظف${pickEmployees('taskEmployee',people)}</label>${field('اليوم','day','date',taskDay)}${field('عنوان المهمة','title')}${field('تعليمات المهمة','notes')}<label>تكرار يوميًا حتى (اختياري)<input name="repeatTo" type="date"></label><p>لو اخترت تاريخ تكرار ستُنشأ المهمة نفسها كل يوم حتى هذا التاريخ (بحد أقصى ٣١ يومًا)، ولن تتكرر مهمة بنفس العنوان في اليوم الواحد.</p>`,f=>createAssignment({employeeId:f.get('taskEmployee'),day:f.get('day'),title:f.get('title'),notes:f.get('notes'),repeatTo:f.get('repeatTo')||undefined}))}
function dailyTasksView(){const people=displayTeam(),ids=new Set(people.map(s=>s.id));const tasks=db.dailyAssignments.filter(t=>ids.has(t.employeeId)&&t.day===taskDay);const taskArticle=t=>`<article class="daily-task"><div><span class="badge">${esc(t.employeeName)} • ${esc(t.department)}</span><h3>${esc(t.title)}</h3><p>${esc(t.notes||'بدون تعليمات إضافية')}</p><small>بواسطة ${esc(t.assignedBy)}</small>${t.completionNote?`<p>تعليق التنفيذ: ${esc(t.completionNote)}</p>`:''}${t.returnReason?`<p>ملاحظات المراجعة: ${esc(t.returnReason)}</p>`:''}</div><div class="task-buttons">${badge(({assigned:'مطلوبة',submitted:'بانتظار المراجعة',approved:'معتمدة',returned:'مطلوب تعديل',legacy_completed:'مكتملة بالنظام السابق',legacy_review:'حالة سابقة للمراجعة'})[t.status])}${role==='الموظف'&&['assigned','returned'].includes(t.status)?`<button data-task-submit="${t.id}" class="primary">تم التنفيذ</button>`:''}${role!=='الموظف'&&t.status==='submitted'?`<button data-task-approve="${t.id}">اعتماد التنفيذ</button><button data-task-return="${t.id}">إرجاع بملاحظة</button>`:''}</div></article>`;const grouped=role==='الموظف'?tasks.map(taskArticle).join(''):[...new Set(tasks.map(t=>t.department||'بدون قسم'))].map(d=>`<h3 class="dept-head" style="margin:14px 0 6px">${esc(d)}</h3>`+tasks.filter(t=>(t.department||'بدون قسم')===d).map(taskArticle).join('')).join('');return `${role==='مدير قسم'?`<div class="notice">مدير قسم تجريبي: ${esc(managerDepartment)}. تقدر تضيف وتراجع مهام فريق القسم المحدد فقط.</div>`:''}${card(role==='الموظف'?'مهامي اليومية':'توزيع ومراجعة مهام الموظفين',`<div class="toolbar"><label>يوم المهام<input id="taskDay" type="date" value="${taskDay}"></label>${role!=='الموظف'?'<button class="primary" id="assignTask">＋ مهمة لموظف</button><button id="floorTasks">قالب مهام المدربين</button><button id="salesTasks">قالب مهام السيلز</button>':''}</div><div class="team-mini-stats"><span>${tasks.length} مهمة</span><span>${tasks.filter(t=>t.status==='submitted').length} بانتظار المراجعة</span><span>${tasks.filter(t=>t.status==='approved').length} معتمدة</span></div>${grouped||'<p class="empty">لا توجد مهام لهذا اليوم. كل موظف يظهر له التكليف الخاص به.</p>'}`)}`}
function changeTask(id,action,note=''){const t=db.dailyAssignments.find(t=>t.id===id);if(!t)throw Error('المهمة غير موجودة');const s=db.staff.find(s=>s.id===t.employeeId);if(action==='submit'){if(role!=='الموظف'||currentEmployee()?.id!==t.employeeId||!['assigned','returned'].includes(t.status))throw Error('لا يمكن إرسال هذه المهمة');t.status='submitted';t.completionNote=requiredText(note,'تعليق التنفيذ');t.completedAt=new Date().toISOString()}else{if(!s||!demoManagerCan(s)||t.status!=='submitted')throw Error('المهمة خارج نطاقك أو ليست بانتظار المراجعة');t.status=action==='approve'?'approved':'returned';if(action!=='approve')t.returnReason=requiredText(note,'سبب الإرجاع');t.reviewedAt=new Date().toISOString()}audit('تحديث مهمة '+t.employeeName+': '+t.status)}
function templateTaskForm(){const people=scopedTeam().filter(s=>employeeDepartment(s)==='التدريب');if(!people.length)return toast('لا يوجد مدربون في نطاقك');safeSubmit('مهام تجهيز الفلور للمدرب',`<label>المدرب${pickEmployees('templateEmployee',people)}</label>${field('اليوم','day','date',taskDay)}<p>سيتم إضافة ٣ مهام مستقلة: ترتيب الفلور، النظافة، والتكييفات. لا يتم تكرار نفس القالب لنفس المدرب واليوم.</p>`,async f=>{const id=Number(f.get('templateEmployee')),day=f.get('day');for(const title of taskTemplates)if(!db.dailyAssignments.some(t=>t.employeeId===id&&t.day===day&&t.title===title))await createAssignment({employeeId:id,day,title,notes:'تأكد من التنفيذ وسجل أي ملاحظة قبل إرسال المهمة للمراجعة.'})})}
const salesTaskTemplates=['الاتصال بكل العملاء المستحقة متابعتهم النهارده وتسجيل النتيجة','تحديث مرحلة كل عميل في الداتا (Source/Open/Follow/Close)','كتابة كومنت واضح لكل مكالمة: العميل قال إيه + الخطوة الجاية + موعد المتابعة','تجهيز قائمة عملاء جدد للأسبوع الجاي'];
function salesTaskForm(){const people=scopedTeam().filter(s=>employeeDepartment(s)==='السيلز');if(!people.length)return toast('لا يوجد سيلز في نطاقك');safeSubmit('قالب مهام السيلز اليومية',`<label>السيلز${pickEmployees('salesTemplateEmployee',people)}</label>${field('اليوم','day','date',taskDay)}<p>سيتم إضافة ٤ مهام مستقلة لمتابعة العملاء والداتا. لا يتم تكرار نفس القالب لنفس الموظف واليوم.</p>`,async f=>{const id=Number(f.get('salesTemplateEmployee')),day=f.get('day');for(const title of salesTaskTemplates)if(!db.dailyAssignments.some(t=>t.employeeId===id&&t.day===day&&t.title===title))await createAssignment({employeeId:id,day,title,notes:'سجل إنجازك بتفاصيله قبل إرسال المهمة للمراجعة.'})})}
function coachPeople(){return displayTeam().filter(s=>employeeDepartment(s)==='التدريب')}
function recordCoaching(data){const s=db.staff.find(s=>s.id===Number(data.employeeId));if(!s||employeeDepartment(s)!=='التدريب'||(role==='الموظف'?currentEmployee()?.id!==s.id:!demoManagerCan(s)))throw Error('تسجيل التمرينات متاح للمدرب الخاص بالسجل فقط');const phone=validPhone(data.phone),clientName=requiredText(data.clientName,'اسم العميل',120),workout=requiredText(data.workout,'التمرينة',1000);const day=data.day||cairoDay();if(!/^\d{4}-\d\d-\d\d$/.test(day)||day>cairoDay())throw Error('اختار يوم صحيح بدون تاريخ مستقبلي');const session={id:crypto.randomUUID(),employeeId:s.id,coachName:s.name,branch:s.branch,clientName,phone,workout,day,createdAt:new Date().toISOString()};db.coachSessions.push(session);audit('تسجيل تمرينة بواسطة '+s.name);return session}
function coachCounts(id,day){const sessions=db.coachSessions.filter(s=>s.employeeId===id&&s.day===day&&!s.voided);return {sessions:sessions.length,clients:new Set(sessions.map(s=>s.phone.replace(/^\+?20/,'0'))).size}}
function coachForm(){const people=coachPeople();if(!people.length)return toast('الموظف المحدد مش مسجل كمدرب');safeSubmit('تسجيل تمرينة عميل',`<label>المدرب${pickEmployees('sessionCoach',people)}</label>${field('اليوم','day','date',cairoDay())}${field('اسم العميل','clientName')}${field('رقم موبايل العميل','phone','tel')}<label>التمرينة اللي عملها العميل<textarea name="workout" required maxlength="1000" rows="4" placeholder="مثال: صدر وترايسبس — التمرينات والملاحظات"></textarea></label>`,f=>recordCoaching({employeeId:f.get('sessionCoach'),day:f.get('day'),clientName:f.get('clientName'),phone:f.get('phone'),workout:f.get('workout')}))}
function coachView(){const people=coachPeople(),ids=new Set(people.map(s=>s.id)),rows=db.coachSessions.filter(s=>ids.has(s.employeeId)&&s.day===coachDay&&!s.voided);return card('سجل تدريب العملاء',`<div class="toolbar"><label>اليوم<input id="coachDay" type="date" value="${coachDay}"></label><button id="addCoaching" class="primary">＋ سجل تمرينة عميل</button></div><div class="coach-counters">${people.map(s=>{const c=coachCounts(s.id,coachDay);return `<div class="coach-counter"><p>${esc(s.name)}</p><strong>${c.clients}</strong><span>عميل خلال اليوم</span><small>${c.sessions} تمرينة مسجلة • العميل المتكرر يُحسب مرة واحدة</small></div>`}).join('')}</div><div class="table-wrap"><table><tr><th>المدرب</th><th>العميل</th><th>رقم الهاتف</th><th>التمرينة</th><th>الوقت</th></tr>${rows.slice().reverse().map(s=>`<tr><td>${esc(s.coachName)}</td><td>${esc(s.clientName)}</td><td dir="ltr">${esc(s.phone)}</td><td style="white-space:pre-wrap;min-width:220px">${esc(s.workout)}</td><td>${stamp(s.createdAt)}</td></tr>`).join('')}</table></div>${rows.length?'':'<p class="empty">لا توجد تمرينات مسجلة لهذا اليوم</p>'}`)}
function salesPeople(){return displayTeam().filter(s=>employeeDepartment(s)==='السيلز')}
function salesCommentReview(comment,nextAction,nextFollowUp){return {kind:'checklist',hasComment:comment.trim().length>=15,hasNextAction:!!nextAction.trim(),hasFollowUp:!!nextFollowUp,aiStatus:'not_connected'}}
function createLead(data){const s=db.staff.find(s=>s.id===Number(data.employeeId));if(!s||employeeDepartment(s)!=='السيلز'||(role==='الموظف'?currentEmployee()?.id!==s.id:!demoManagerCan(s)))throw Error('العميل خارج فريقك');const phone=validPhone(data.phone);if(db.salesLeads.some(l=>l.phone===phone))throw Error('رقم العميل موجود بالفعل؛ راجع السجل لتجنب تكرار الداتا');if(!leadSources.includes(data.source))throw Error('اختار المصدر');const lead={id:crypto.randomUUID(),employeeId:s.id,employeeName:s.name,branch:s.branch,name:requiredText(data.name,'اسم العميل',120),phone,source:data.source,stage:'Source',comments:[],createdAt:new Date().toISOString()};if(String(data.comment||'').trim()){lead.comments.push({id:crypto.randomUUID(),comment:String(data.comment).trim().slice(0,2000),at:lead.createdAt,outcome:'',nextAction:'',nextFollowUp:'',review:salesCommentReview(String(data.comment),'','')})}db.salesLeads.push(lead);audit('إضافة داتا سيلز بواسطة '+s.name);return lead}
function salesForm(){const people=salesPeople();if(!people.length)return toast('لا يوجد سيلز في نطاق العرض');safeSubmit('إضافة داتا عميل',`<label>الموظف${pickEmployees('leadEmployee',people)}</label>${field('اسم العميل','name')}${field('رقم الموبايل','phone','tel')}${options('مصدر الداتا','source',leadSources)}<label>الكومنت / ملاحظات العميل<textarea name="comment" rows="4" maxlength="2000" placeholder="اكتب ملاحظات العميل أو تفاصيل أول تواصل"></textarea></label>`,f=>createLead({employeeId:f.get('leadEmployee'),name:f.get('name'),phone:f.get('phone'),source:f.get('source'),comment:f.get('comment')}))}
function canSeeLead(l){return salesPeople().some(s=>s.id===l.employeeId)}
function leadUpdateForm(id){const lead=db.salesLeads.find(l=>l.id===id);if(!lead||!canSeeLead(lead))return toast('العميل خارج نطاقك');safeSubmit('متابعة '+lead.name,`${options('مرحلة العميل','stage',leadStages)}${options('نتيجة المكالمة','outcome',callOutcomes)}${field('الخطوة الجاية','nextAction','text',lead.nextAction||'')}<label>موعد المتابعة القادم بتوقيت القاهرة<input name="nextFollowUp" type="datetime-local" value="${lead.nextFollowUp?cairoInput(lead.nextFollowUp):''}"></label><label>تفاصيل المكالمة / الكومنت<textarea name="comment" required rows="4" maxlength="2000" placeholder="العميل قال إيه؟ اعتراضه إيه؟ اتفقتوا على إيه؟"></textarea></label><p>مراجعة AI غير مفعلة في المعاينة. يتم فقط إظهار اكتمال حقول التعليق والخطوة الجاية والمتابعة.</p>`,f=>{if(!canSeeLead(lead))throw Error('غير مسموح');const comment=requiredText(f.get('comment'),'تفاصيل المكالمة',2000),nextAction=String(f.get('nextAction')||'').trim(),nextFollowUp=f.get('nextFollowUp')?cairoToISO(f.get('nextFollowUp')):'';lead.stage=f.get('stage');lead.outcome=f.get('outcome');lead.nextAction=nextAction;lead.nextFollowUp=nextFollowUp;lead.comments.push({id:crypto.randomUUID(),comment,nextAction,nextFollowUp,outcome:lead.outcome,at:new Date().toISOString(),review:salesCommentReview(comment,nextAction,nextFollowUp)});audit('تحديث متابعة سيلز بواسطة '+lead.employeeName)});$('#fields select[name="stage"]').value=lead.stage}
function salesView(){const rows=db.salesLeads.filter(l=>canSeeLead(l)&&(salesStage==='all'||l.stage===salesStage)&&(salesSource==='all'||l.source===salesSource)&&(!salesQuery||(l.name+l.phone).includes(salesQuery)));return `<div class="notice">تم الحفاظ على مصادر ومراحل النظام القديم. مراجعة AI لم يتم توصيلها؛ قائمة الاكتمال أدناه فحص حقول فقط، وليست تقييمًا للموظف أو قرار جزاء.</div>${card('داتا السيلز والمتابعات',`<div class="toolbar sales-filters"><button id="newSalesLead" class="primary">＋ عميل جديد</button><select id="salesStage"><option value="all">كل المراحل</option>${leadStages.map(x=>`<option ${salesStage===x?'selected':''}>${x}</option>`).join('')}</select><select id="salesSource"><option value="all">كل المصادر</option>${leadSources.map(x=>`<option ${salesSource===x?'selected':''}>${x}</option>`).join('')}</select><input id="salesSearch" placeholder="اسم العميل أو رقم الهاتف" value="${esc(salesQuery)}"><button id="salesSearchGo">بحث</button></div><div class="pipeline-counts">${leadStages.map(stage=>`<span><b>${db.salesLeads.filter(l=>canSeeLead(l)&&l.stage===stage).length}</b>${stage}</span>`).join('')}</div>${rows.map(l=>{const last=l.comments.at(-1),r=last?.review;return `<article class="sales-lead"><div class="lead-heading"><div><h3>${esc(l.name)} <small dir="ltr">${esc(l.phone)}</small></h3><p>${esc(l.employeeName)} • ${esc(l.source)} • ${esc(l.stage)}</p>${(db.assessmentBookings||[]).filter(b=>String(b.leadId||'')===String(l.id)).slice(-2).map(b=>`<p class="lead-assess">✦ أسسمنت ${esc(b.day)} ${esc(b.time)} — ${esc(b.doctorName)} — ${esc(({booked:'محجوز',postponed:'مؤجل',attended:'حضر',completed:'تم الكشف',no_show:'لم يحضر',cancelled:'ملغي'})[b.bookingStatus]||b.bookingStatus)}</p>`).join('')}</div><div class="lead-actions"><button data-lead-update="${l.id}">تسجيل متابعة</button><button data-lead-comment="${l.id}">＋ كومنت</button><button data-lead-assess="${l.id}">✦ حجز أسسمنت</button></div></div>${last?`<blockquote>${esc(last.comment)}</blockquote><p>النتيجة: ${esc(last.outcome)} • الخطوة الجاية: ${esc(last.nextAction||'غير محددة')}<br>المتابعة: ${last.nextFollowUp?stamp(last.nextFollowUp):'غير محددة'}</p><div class="comment-checks"><span>${r.hasComment?'✓':'○'} تفاصيل التعليق</span><span>${r.hasNextAction?'✓':'○'} الخطوة الجاية</span><span>${r.hasFollowUp?'✓':'○'} موعد المتابعة</span><small>AI غير متصل</small></div><details><summary>سجل التعليقات (${l.comments.length})</summary>${l.comments.slice().reverse().map(c=>`<div class="activity"><p>${stamp(c.at)}<br>${esc(c.comment)}</p></div>`).join('')}</details>`:'<p>لم تسجل متابعة بعد</p>'}</article>`}).join('')||'<p class="empty">لا توجد داتا في النطاق المحدد</p>'}`)}`}
function splitAttendanceButtons(){const s=currentEmployee(),old=$('#geoPunch');if(!s||!old)return;const active=!!activePunch(s.id);old.outerHTML=`<div class="attendance-actions"><button id="attendanceIn" class="primary" ${active||geoBusy?'disabled':''}>تسجيل حضور ⟵</button><button id="attendanceOut" ${!active||geoBusy?'disabled':''}>تسجيل انصراف ⟶</button></div>`;$('#attendanceIn').onclick=()=>{if(activePunch(s.id))return toast('في حضور مفتوح بالفعل');punch()};$('#attendanceOut').onclick=()=>{if(!activePunch(s.id))return toast('لا يوجد حضور مفتوح');if(activeBreak(s.id))return toast('أنهِ البريك أولًا');punch()}}
render=function(){if(role==='مدير قسم'&&!['overview','daily-team','coach-log','sales-work','sales-calls','policy','sales-dashboard'].includes(page))page='daily-team';if(role==='الموظف'&&!['overview','join','daily-team','coach-log','sales-work','sales-calls','policy'].includes(page))page='overview';teamRender();const employeeMode=role==='الموظف',managerMode=role==='مدير قسم';if(employeeMode)splitAttendanceButtons();const s=currentEmployee();if(employeeMode){const permitted=new Set(['overview','daily-team','join','policy',...(employeeDepartment(s||{})==='التدريب'?['coach-log']:[]),...(employeeDepartment(s||{})==='السيلز'?['sales-work','sales-calls']:[])]);document.querySelectorAll('#nav [data-page]').forEach(b=>b.hidden=!permitted.has(b.dataset.page));$('#app').insertAdjacentHTML('afterbegin','<div class="notice" data-preview-only>اختيار الموظف أعلاه لمعاينة حسابه فقط. الدخول والموافقة والبيانات هنا على نفس المتصفح، وليست حسابات فعلية.</div>')}
if(managerMode){const allowed=new Set(['overview','daily-team','coach-log','sales-work','sales-calls','policy','sales-dashboard']);document.querySelectorAll('#nav [data-page]').forEach(b=>b.hidden=!allowed.has(b.dataset.page));$('#add').textContent='＋ مهمة لموظف';$('#add').onclick=taskForm;$('#app').insertAdjacentHTML('afterbegin',`<div class="notice" data-preview-only>معاينة مدير قسم فقط <select id="managerDept">${departments.map(d=>`<option ${d===managerDepartment?'selected':''}>${d}</option>`).join('')}</select></div>`);$('#managerDept').onchange=e=>{managerDepartment=e.target.value;render()}}
if(page==='join'){ $('#app').innerHTML=joinView();$('#joinForm').onsubmit=e=>{e.preventDefault();try{newJoin(Object.fromEntries(new FormData(e.target)));save();render();toast('تم إرسال طلب المعاينة. افتح الإدارة ← طلبات الانضمام')}catch(e){toast(e.message)}}}
if(page==='join-approvals'){if(role!=='الإدارة'){$('#app').innerHTML='<p class="empty">مراجعة الانضمام متاحة للإدارة فقط</p>';return}$('#app').innerHTML=approvalsView();document.querySelectorAll('[data-join-approve]').forEach(b=>b.onclick=()=>{const r=db.joinRequests.find(r=>r.id===b.dataset.joinApprove);safeSubmit('تحديد وظيفة وأكسس '+r.name,options('الوظيفة المعتمدة','position',Object.keys(positions))+options('الفرع المعتمد','branch',db.branches.map(b=>b.name))+'<p>هيظهر الموظف في قائمة معاينة حسابات الموظفين، بدون إنشاء باسورد أو حساب فعلي.</p>',f=>approveJoin(r.id,f.get('position'),f.get('branch')));$('#fields select[name="position"]').value=r.position;$('#fields select[name="branch"]').value=r.branch});document.querySelectorAll('[data-join-reject]').forEach(b=>b.onclick=()=>safeSubmit('رفض طلب الانضمام',field('سبب الرفض','reason'),f=>{const r=db.joinRequests.find(r=>r.id===b.dataset.joinReject);if(r.status!=='pending')throw Error('الطلب اتراجع بالفعل');r.reason=requiredText(f.get('reason'),'سبب الرفض');r.status='rejected';r.reviewedAt=new Date().toISOString();audit('رفض طلب انضمام: '+r.name)}))}
if(page==='daily-team'){$('#app').innerHTML=dailyTasksView();$('#taskDay').onchange=e=>{if(e.target.value){taskDay=e.target.value;render()}};$('#assignTask')?.addEventListener('click',taskForm);$('#floorTasks')?.addEventListener('click',templateTaskForm);$('#salesTasks')?.addEventListener('click',salesTaskForm);for(const [attr,action] of [['taskSubmit','submit'],['taskApprove','approve'],['taskReturn','return']])document.querySelectorAll('[data-'+attr.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())+']').forEach(b=>b.onclick=async()=>{if(action==='approve'){try{await changeTask(b.dataset[attr],action);render()}catch(e){toast(e.message)}}else safeSubmit(action==='submit'?'إرسال التنفيذ للمراجعة':'إرجاع المهمة',field(action==='submit'?'تعليق التنفيذ':'سبب الإرجاع','note'),f=>changeTask(b.dataset[attr],action,f.get('note')))})}
if(page==='coach-log'){$('#app').innerHTML=coachView();$('#coachDay').onchange=e=>{if(e.target.value){coachDay=e.target.value;render()}};$('#addCoaching').onclick=coachForm}
if(page==='sales-work'){$('#app').innerHTML=salesView();$('#newSalesLead').onclick=salesForm;$('#salesStage').onchange=e=>{salesStage=e.target.value;render()};$('#salesSource').onchange=e=>{salesSource=e.target.value;render()};$('#salesSearchGo').onclick=()=>{salesQuery=$('#salesSearch').value.trim();render()};document.querySelectorAll('[data-lead-update]').forEach(b=>b.onclick=()=>leadUpdateForm(b.dataset.leadUpdate));document.querySelectorAll('[data-lead-comment]').forEach(b=>b.onclick=()=>leadCommentForm(b.dataset.leadComment));document.querySelectorAll('[data-lead-assess]').forEach(b=>b.onclick=()=>bookAssessmentForLead(b.dataset.leadAssess))}
if(employeeMode&&page!=='overview'&&page!=='join'){$('#app').insertAdjacentHTML('afterbegin',`<div class="notice" data-preview-only>معاينة حساب الموظف ${pickEmployees('teamPreviewEmployee',db.staff,currentEmployee()?.id)} — بدون تسجيل دخول فعلي</div>`);$('#teamPreviewEmployee').onchange=e=>{selectedEmployee=Number(e.target.value);render()}}if(employeeMode&&page==='overview'&&s&&employeeDepartment(s)==='التدريب'){const c=coachCounts(s.id,cairoDay());$('#app').insertAdjacentHTML('afterbegin',`<div class="coach-counter"><p>أداء التدريب النهارده</p><strong>${c.clients}</strong><span>عميل تم تدريبه • ${c.sessions} تمرينة مسجلة</span><button id="quickCoachLog">افتح سجل التمرينات</button></div>`);$('#quickCoachLog').onclick=()=>{page='coach-log';render()}}if(managerMode&&page!=='overview'){$('#app').insertAdjacentHTML('afterbegin',`<div class="notice" data-preview-only>معاينة مدير القسم <select id="finalManagerDept">${departments.map(d=>`<option ${d===managerDepartment?'selected':''}>${d}</option>`).join('')}</select></div>`);$('#finalManagerDept').onchange=e=>{managerDepartment=e.target.value;render()}}if(role==='الإدارة'){const n=db.joinRequests.filter(r=>r.status==='pending').length;if(n&&page!=='join-approvals'){$('#app').insertAdjacentHTML('afterbegin',`<div class="notice">${n} طلبات انضمام جديدة بانتظار الموافقة الأولى <button id="openJoinApprovals">مراجعة الطلبات</button></div>`);$('#openJoinApprovals').onclick=()=>{page='join-approvals';render()}}}
};
if(!Array.from($('#role').options).some(o=>o.value==='مدير قسم'))$('#role').insertAdjacentHTML('beforeend','<option>مدير قسم</option>');
render();
